-- pintopets_pets: tenant-scoped rows behind /pets (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_pets (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            owner_user_uuid UUID NOT NULL,
            name VARCHAR(255) NOT NULL,
            species VARCHAR(255) NOT NULL,
            species_other VARCHAR(255),
            breeds VARCHAR(255),
            sex VARCHAR(255) NOT NULL,
            neutered VARCHAR(255) NOT NULL,
            date_of_birth DATE,
            date_of_birth_is_estimate BOOLEAN,
            colour_markings VARCHAR(255),
            height_inches INTEGER,
            passport_number VARCHAR(255),
            insurance_provider VARCHAR(255),
            insurance_policy_ref VARCHAR(255),
            vet_practice_name VARCHAR(255),
            vet_practice_phone VARCHAR(255),
            emergency_contact_name VARCHAR(255),
            emergency_contact_phone VARCHAR(255),
            notes TEXT,
            status VARCHAR(255) NOT NULL,
            deceased_on DATE,
            profile_photo_uuid UUID,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT pintopets_pets_sex_check CHECK (sex IN ('male', 'female', 'unknown')),
            CONSTRAINT pintopets_pets_neutered_check CHECK (neutered IN ('yes', 'no', 'unknown')),
            CONSTRAINT pintopets_pets_status_check CHECK (status IN ('active', 'archived', 'deceased')),
            CONSTRAINT pintopets_pets_height_inches_range CHECK (height_inches BETWEEN 20 AND 90)
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_pets_namespace ON pintopets_pets (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_pets_owner ON pintopets_pets (namespace_id, owner_user_uuid)")
end
